function icon(string $name, ?int $size = null, string $class = ""): string
{
    $paths = ICON_PATHS[$name] ?? ICON_PATHS["home"];
    $dimension = $size ? $size . "px" : "1em";

    return '<svg class="i i-' . $name . ($class !== "" ? " " . $class : "") . '" width="' . $dimension . '" height="' . $dimension
        . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"'
        . ' stroke-linejoin="round" aria-hidden="true" focusable="false">' . $paths . '</svg>';
}
